/**
 * Evaluation Data and Target Contracts — Research Prototype.
 *
 * Defines the contract standards for evaluating candidate means-testing models:
 * 1. Dataset Manifests: Documented provenance, sampling design, weights, and governance approval.
 * 2. Independent Evaluation Targets: Rigorously defined reference outcomes that come from
 *    external ground truth, NEVER generated by candidate models.
 * 3. Compatibility Validation: Prevents evaluating models on incompatible constructs, mismatched
 *    units, or conflated observation periods.
 */

export const EVALUATION_DATASET_TYPES = Object.freeze({
  SYNTHETIC: "SYNTHETIC",
  SURVEY: "SURVEY",
  ADMINISTRATIVE: "ADMINISTRATIVE",
  OTHER_APPROVED: "OTHER_APPROVED"
});

export const EVALUATION_TARGET_TYPES = Object.freeze({
  CONTINUOUS: "CONTINUOUS",
  BINARY: "BINARY",
  CATEGORICAL: "CATEGORICAL"
});

/**
 * Validates a dataset manifest against governance standards.
 */
export function validateDatasetManifest(manifest) {
  const errors = [];

  if (!manifest || typeof manifest !== "object") {
    return { isValid: false, errors: ["Dataset manifest must be an object."] };
  }

  if (!manifest.id || typeof manifest.id !== "string") {
    errors.push("Dataset manifest requires a unique string identifier.");
  }

  if (!manifest.version || typeof manifest.version !== "string") {
    errors.push("Dataset manifest requires a version string.");
  }

  if (!manifest.datasetType || !Object.values(EVALUATION_DATASET_TYPES).includes(manifest.datasetType)) {
    errors.push(`Dataset type must be one of: ${Object.values(EVALUATION_DATASET_TYPES).join(", ")}.`);
  }

  if (typeof manifest.recordCount !== "number" || manifest.recordCount < 0) {
    errors.push("Dataset manifest requires a valid non-negative recordCount.");
  }

  if (!manifest.observationPeriod || typeof manifest.observationPeriod !== "object") {
    errors.push("Dataset manifest requires an observationPeriod object ({ startDate, endDate, windowMonths }).");
  }

  if (typeof manifest.isApprovedForEmpiricalEvaluation !== "boolean") {
    errors.push("Dataset manifest requires an isApprovedForEmpiricalEvaluation boolean flag.");
  }

  // Safety rule: Synthetic datasets can NEVER be approved for empirical evaluation
  if (manifest.datasetType === EVALUATION_DATASET_TYPES.SYNTHETIC && manifest.isApprovedForEmpiricalEvaluation === true) {
    errors.push("Governance violation: Synthetic datasets cannot be approved for empirical evaluation.");
  }

  return {
    isValid: errors.length === 0,
    errors
  };
}

/**
 * Validates an evaluation target definition.
 */
export function validateTargetDefinition(target) {
  const errors = [];

  if (!target || typeof target !== "object") {
    return { isValid: false, errors: ["Target definition must be an object."] };
  }

  if (!target.id || typeof target.id !== "string") {
    errors.push("Target definition requires a unique string identifier.");
  }

  if (!target.targetType || !Object.values(EVALUATION_TARGET_TYPES).includes(target.targetType)) {
    errors.push(`Target type must be one of: ${Object.values(EVALUATION_TARGET_TYPES).join(", ")}.`);
  }

  if (!target.unit || typeof target.unit !== "string") {
    errors.push("Target definition requires a unit of measurement (e.g. 'KSh/year', 'BOOLEAN_STATUS').");
  }

  if (!target.referenceField || typeof target.referenceField !== "string") {
    errors.push("Target definition requires a referenceField name pointing to independent data.");
  }

  if (target.targetType === EVALUATION_TARGET_TYPES.BINARY) {
    if (typeof target.positiveClassValue === "undefined") {
      errors.push("Binary target definition requires an explicit positiveClassValue.");
    }
  }

  if (!target.independentProvenance || typeof target.independentProvenance !== "string") {
    errors.push("Target definition requires documented independentProvenance explaining ground truth source.");
  }

  return {
    isValid: errors.length === 0,
    errors
  };
}

/**
 * Validates whether a candidate model prediction and reference target share defensible
 * compatibility, units, and observation periods.
 */
export function validatePredictionReferenceCompatibility({ modelRegistryEntry, targetDefinition, datasetManifest }) {
  const blockers = [];

  if (!modelRegistryEntry) {
    blockers.push("Model registry entry is missing.");
    return { isCompatible: false, blockers };
  }

  if (!targetDefinition) {
    blockers.push("Target definition is missing.");
    return { isCompatible: false, blockers };
  }

  // 1. Official baseline check: cannot evaluate against an unconfigured baseline
  if (modelRegistryEntry.isOfficialShaBaseline && modelRegistryEntry.status !== "CONFIGURED") {
    blockers.push(`Comparative evaluation blocked: Official SHA baseline is not configured (${modelRegistryEntry.statusReason || "official parameters required"}).`);
  }

  // 2. Self-evaluation safeguard: Candidate model cannot generate its own reference outcome
  if (targetDefinition.generatedByModelId && targetDefinition.generatedByModelId === modelRegistryEntry.id) {
    blockers.push(`Methodological violation: Candidate model '${modelRegistryEntry.id}' cannot be evaluated against its own generated outcome.`);
  }

  // 3. Unit and construct compatibility check
  const targetUnit = targetDefinition.unit;
  const modelOutputUnit = modelRegistryEntry.primaryOutputUnit;

  if (targetDefinition.targetType === EVALUATION_TARGET_TYPES.CONTINUOUS) {
    if (targetUnit !== modelOutputUnit) {
      blockers.push(`Incompatible units: Target unit '${targetUnit}' does not match model output unit '${modelOutputUnit}'.`);
    }
  }

  // 4. Observation period alignment check
  if (datasetManifest?.observationPeriod && targetDefinition.observationPeriod) {
    const dsMonths = datasetManifest.observationPeriod.windowMonths;
    const tgtMonths = targetDefinition.observationPeriod.windowMonths;
    if (dsMonths && tgtMonths && dsMonths !== tgtMonths) {
      blockers.push(`Observation period mismatch: Dataset spans ${dsMonths} months, but target definition requires ${tgtMonths} months.`);
    }
  }

  return {
    isCompatible: blockers.length === 0,
    blockers
  };
}

